css:
:root {
  --panel-padding: 24px;

  --title-color: #0E5B67;
  --subtitle-color: #728DA5;

  --tend-border: #426B86;
  --tend-text: #24475F;
  --tend-icon: #426B86;

  --tend-light: #F4F9FC;
  --tend-middle: #DFEDF4;
  --tend-base: #C5DDE9;

  --tend-tracks: 8;
  --tend-rows: 4;
  --tend-gap: 16px;

  --card-padding: 12px;
  --card-radius: 5px;
  --card-font: 15.5px;
  --card-icon: 40px;
  --card-content-gap: 8px;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;

  border: none;
  overflow: hidden;
  background: transparent !important;

  pointer-events: none;
}

.tendencias-widget,
.tendencias-widget * {
  box-sizing: border-box;
}

.tendencias-widget {
  position: relative;
  display: flex;
  flex-direction: column;

  width: 100%;
  height: 100%;
  padding: 92px var(--panel-padding) var(--panel-padding);

  border: none;
  background: transparent;
  overflow: hidden;

  user-select: none;
  pointer-events: none;
}

/* Encabezado común a las pantallas de Línea 3. */
.tendencias-header {
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 70px;
  padding: 14px 30px 0;
  margin: 0;

  border: none;
  background: transparent;
}

.tendencias-title {
  margin: 0;
  padding: 0;

  color: var(--title-color);

  font-family: Arial, "Segoe UI", sans-serif;
  font-size: 28px;
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: 0;

  text-align: left;
  white-space: nowrap;
}

.tendencias-subtitle {
  margin: 5px 0 0;
  padding: 0;

  color: var(--subtitle-color);

  font-family: Arial, "Segoe UI", sans-serif;
  font-size: 14px;
  font-weight: 400;
  line-height: 1.3;
  letter-spacing: 0;

  text-align: left;
  white-space: nowrap;
}

/* Área disponible para las tarjetas. */
.tendencias-stage {
  display: flex;
  flex: 1 1 auto;

  align-items: center;
  justify-content: center;

  width: 100%;
  min-height: 0;

  border: none;
  background: transparent;
}

.tendencias-grid {
  display: grid;

  grid-template-columns:
    repeat(var(--tend-tracks), minmax(0, 1fr));

  grid-template-rows:
    repeat(var(--tend-rows), minmax(0, 1fr));

  gap: var(--tend-gap);

  width: 100%;
  height: 100%;

  max-width: 1280px;
  max-height: 548px;

  border: none;
  background: transparent;
}

/* Rectángulos estáticos con redondeo discreto. */
.tendencia-card {
  display: flex;
  flex-direction: column;

  align-items: center;
  justify-content: center;

  grid-column: span 2;
  gap: var(--card-content-gap);

  min-width: 0;
  min-height: 0;
  padding: var(--card-padding);

  border: 1.5px solid var(--tend-border);
  border-radius: var(--card-radius);

  background: linear-gradient(
    145deg,
    var(--tend-light) 0%,
    var(--tend-middle) 52%,
    var(--tend-base) 100%
  );

  box-shadow:
    inset 0 1px 1px rgba(255, 255, 255, 0.85),
    inset 0 -2px 4px rgba(39, 78, 100, 0.12);

  color: var(--tend-text);
  overflow: hidden;
  pointer-events: none;
}

.tendencia-label {
  display: flex;
  flex: 0 0 auto;
  flex-direction: column;

  align-items: center;
  justify-content: center;

  width: 100%;
  min-width: 0;

  font-family:
    "Bahnschrift",
    "Segoe UI",
    Arial,
    sans-serif;

  font-size: var(--card-font);
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: 0.1px;

  text-align: center;
}

.tendencia-label > span {
  display: block;
  max-width: 100%;
  white-space: nowrap;
}

/* Base de los íconos monocromáticos. */
.tendencia-icon {
  position: relative;

  display: flex;
  flex: 0 0 auto;

  align-items: center;
  justify-content: center;

  width: 1.5em;
  height: 1.05em;

  color: var(--tend-icon);

  font-family:
    "Segoe UI Symbol",
    "Bahnschrift",
    Arial,
    sans-serif;

  font-size: var(--card-icon);
  font-weight: 400;
  line-height: 1;

  pointer-events: none;
}

.tendencia-icon i {
  position: absolute;
  display: block;
  font-style: normal;
}

/* Temperatura. */
.icon-temperature {
  font-family: "Bahnschrift", "Segoe UI", Arial, sans-serif;
  font-weight: 500;
  letter-spacing: -0.05em;
}

.icon-temperature > span {
  font-size: 0.85em;
}

/* Lazos críticos. */
.icon-critical > span {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 1.35em;
  height: 1.35em;

  border: 0.09em solid currentColor;
  border-radius: 50%;

  font-family: "Bahnschrift", Arial, sans-serif;
  font-size: 0.65em;
  font-weight: 600;
}

/* Flujos. */
.icon-flow > span {
  font-size: 1.05em;
}

/* Vapor. */
.icon-steam > span {
  display: block;
  transform: rotate(-90deg);
}

/* RIZADORA: rodillos estriados con fibra entre ellos. */
.icon-crimper .roller {
  left: 0.28em;

  width: 0.94em;
  height: 0.28em;

  border: 0.045em solid currentColor;
  border-radius: 0.07em;

  background: repeating-linear-gradient(
    90deg,
    transparent 0,
    transparent 0.10em,
    currentColor 0.10em,
    currentColor 0.135em
  );
}

.icon-crimper .roller-top {
  top: 0.10em;
}

.icon-crimper .roller-bottom {
  bottom: 0.10em;
}

.icon-crimper .fiber {
  left: 0.16em;
  top: 0.44em;

  width: 1.18em;
  height: 0.16em;

  background: currentColor;

  clip-path: polygon(
    0 40%, 15% 40%,
    22% 0, 32% 65%,
    42% 0, 52% 65%,
    62% 0, 72% 65%,
    82% 40%, 100% 40%,
    100% 65%, 84% 65%,
    72% 100%, 62% 35%,
    52% 100%, 42% 35%,
    32% 100%, 22% 35%,
    17% 65%, 0 65%
  );
}

/*
 * CONDUCTIVIDAD:
 * gota del baño de proceso, cargas iónicas y unidad µS/cm.
 */
.icon-conductivity .drop {
  left: 0.54em;
  top: 0.10em;

  width: 0.42em;
  height: 0.42em;

  border: 0.045em solid currentColor;
  border-radius: 0 50% 50% 50%;

  transform: rotate(45deg);
}

.icon-conductivity .ion {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 1.15em;
  height: 1.15em;

  border: 0.10em solid currentColor;
  border-radius: 50%;

  font-family: Arial, sans-serif;
  font-size: 0.25em;
  font-weight: 600;
  line-height: 1;
}

.icon-conductivity .ion-positive {
  left: 0.7em;
  top: 0.8em;
}

.icon-conductivity .ion-negative {
  right: 0.7em;
  top: 0.8em;
}

.icon-conductivity .conductivity-unit {
  left: 0;
  bottom: 0.02em;

  width: 100%;

  font-family: "Bahnschrift", "Segoe UI", Arial, sans-serif;
  font-size: 0.28em;
  font-weight: 600;
  line-height: 1;

  text-align: center;
  white-space: nowrap;
}

/*
 * VELOCIDAD DE TAMBORES:
 * rodillos de arrastre, recorrido de fibra y unidad m/min.
 */
.icon-drum .drum-roller {
  top: 0.27em;

  width: 0.40em;
  height: 0.40em;

  border: 0.045em solid currentColor;
  border-radius: 50%;
}

.icon-drum .drum-left {
  left: 0.22em;
}

.icon-drum .drum-right {
  right: 0.22em;
}

.icon-drum .drum-roller::after {
  content: "";
  position: absolute;

  left: 50%;
  top: 50%;

  width: 0.07em;
  height: 0.07em;

  border-radius: 50%;
  background: currentColor;

  transform: translate(-50%, -50%);
}

.icon-drum .fiber-route {
  left: 0.08em;
  top: 0.20em;

  width: 1.28em;
  height: 0.045em;

  background: currentColor;
}

.icon-drum .fiber-route::after {
  content: "";
  position: absolute;

  right: -0.04em;
  top: -0.06em;

  border-top: 0.08em solid transparent;
  border-bottom: 0.08em solid transparent;
  border-left: 0.13em solid currentColor;
}

.icon-drum .drum-link {
  left: 0.61em;
  top: 0.45em;

  width: 0.28em;
  height: 0.045em;

  background: currentColor;
}

.icon-drum .speed-unit {
  left: 0;
  bottom: 0.02em;

  width: 100%;

  font-family: "Bahnschrift", "Segoe UI", Arial, sans-serif;
  font-size: 0.27em;
  font-weight: 600;
  line-height: 1;

  text-align: center;
  white-space: nowrap;
}

/* MOTOR PRINCIPAL: basado en la imagen de referencia. */
.icon-motor .motor-reference {
  position: relative;
  display: block;

  width: 1.35em;
  height: 1em;

  color: var(--tend-icon);
}

/* Cubierta posterior con aletas horizontales. */
.icon-motor .motor-rear-cover {
  left: 7%;
  top: 19%;

  width: 26%;
  height: 60%;

  border: 0.035em solid currentColor;
  border-radius: 28% 0 0 28%;

  background:
    repeating-linear-gradient(
      to bottom,
      transparent 0,
      transparent 0.11em,
      currentColor 0.11em,
      currentColor 0.14em
    ),
    var(--tend-middle);
}

/* Eje visible a la derecha. */
.icon-motor .motor-output-shaft {
  left: 75%;
  top: 25%;

  width: 22%;
  height: 14%;

  border: 0.035em solid currentColor;

  background:
    repeating-linear-gradient(
      to right,
      transparent 0,
      transparent 0.085em,
      currentColor 0.085em,
      currentColor 0.115em
    ),
    var(--tend-light);
}

/* Patas de soporte. */
.icon-motor .motor-support {
  top: 74%;

  width: 17%;
  height: 19%;

  border: 0.035em solid currentColor;
  background: var(--tend-middle);
}

.icon-motor .motor-support-left {
  left: 23%;
  transform: skewX(-18deg);
}

.icon-motor .motor-support-right {
  left: 62%;
  transform: skewX(18deg);
}

/* Bases de fijación. */
.icon-motor .motor-base {
  top: 91%;

  width: 25%;
  height: 6%;

  border: 0.025em solid currentColor;
  background: var(--tend-light);
}

.icon-motor .motor-base-left {
  left: 16%;
}

.icon-motor .motor-base-right {
  left: 60%;
}

/* Carcasa principal rectangular. */
.icon-motor .motor-main-housing {
  left: 28%;
  top: 5%;

  width: 49%;
  height: 75%;

  border: 0.035em solid currentColor;
  border-radius: 0.015em;

  background: var(--tend-light);
}

/* Aletas horizontales de refrigeración. */
.icon-motor .motor-horizontal-fins {
  left: 31%;
  top: 14%;

  width: 43%;
  height: 58%;

  border-top: 0.035em solid currentColor;
  border-bottom: 0.035em solid currentColor;

  background: repeating-linear-gradient(
    to bottom,
    transparent 0,
    transparent 0.10em,
    currentColor 0.10em,
    currentColor 0.135em
  );
}

/* Unión vertical de la cubierta posterior. */
.icon-motor .motor-rear-band {
  left: 13%;
  top: 18%;

  width: 0.035em;
  height: 61%;

  background: currentColor;
}

/* CORRIENTE: descarga eléctrica y conductor. */
.icon-current .bolt {
  left: 0.51em;
  top: 0.02em;

  width: 0.49em;
  height: 0.69em;

  background: currentColor;

  clip-path: polygon(
    43% 0,
    100% 0,
    64% 37%,
    100% 37%,
    16% 100%,
    39% 55%,
    0 55%
  );
}

.icon-current .wire {
  left: 0.31em;
  bottom: 0.15em;

  width: 0.88em;
  height: 0.045em;

  background: currentColor;
}

.icon-current .terminal {
  bottom: 0.10em;

  width: 0.14em;
  height: 0.14em;

  border: 0.04em solid currentColor;
  border-radius: 50%;
}

.icon-current .terminal-left {
  left: 0.20em;
}

.icon-current .terminal-right {
  right: 0.20em;
}

