"use strict";

(function () {
  const DEFAULT_TITLE = "LÍNEA 3 / TENDENCIAS";

  const DEFAULT_SUBTITLE =
    "Seguimiento de variables del proceso de acabado de fibra e hilos";

  const ITEMS = [
    {
      icon: "temperature",
      lines: ["Temperatura", "Cubas de Lavado"]
    },
    {
      icon: "critical",
      lines: ["Lazos Críticos", "Lavadora"]
    },
    {
      icon: "critical",
      lines: ["Lazos Críticos", "PreEstiro"]
    },
    {
      icon: "critical",
      lines: ["Lazos Críticos", "Estiro"]
    },
    {
      icon: "critical",
      lines: ["Lazos Críticos", "Secadora"]
    },
    {
      icon: "flow",
      lines: ["Flujos", "Lavadoras"]
    },
    {
      icon: "crimper",
      lines: ["Rizadoras"]
    },
    {
      icon: "steam",
      lines: ["Vapor"]
    },
    {
      icon: "conductivity",
      lines: ["Conductividad"]
    },
    {
      icon: "temperature",
      lines: ["Temperatura", "de Tanques"]
    },
    {
      icon: "drum",
      lines: ["Velocidad", "de Tambores"]
    },
    {
      icon: "motor",
      lines: ["Motor Principal"]
    },
    {
      icon: "current",
      lines: ["Corriente Ventiladores", "1 al 11"]
    },
    {
      icon: "current",
      lines: ["Corriente Ventiladores", "12 al 22"]
    }
  ];

  /*
   * Íconos construidos con HTML y CSS.
   * No requieren imágenes, SVG ni fuentes externas.
   */
  const ICONS = {
    temperature: "<span>°C</span>",

    critical: "<span>!</span>",

    flow: "<span>⇄</span>",

    steam: "<span>≋</span>",

    crimper: `
      <i class="roller roller-top"></i>
      <i class="roller roller-bottom"></i>
      <i class="fiber"></i>
    `,

    conductivity: `
      <i class="drop"></i>
      <i class="ion ion-positive">+</i>
      <i class="ion ion-negative">−</i>
      <i class="conductivity-unit">µS/cm</i>
    `,

    drum: `
      <i class="drum-roller drum-left"></i>
      <i class="drum-roller drum-right"></i>
      <i class="fiber-route"></i>
      <i class="drum-link"></i>
      <i class="speed-unit">m/min</i>
    `,

    motor: `
      <span class="motor-reference">
        <i class="motor-rear-cover"></i>
        <i class="motor-output-shaft"></i>

        <i class="motor-support motor-support-left"></i>
        <i class="motor-support motor-support-right"></i>

        <i class="motor-base motor-base-left"></i>
        <i class="motor-base motor-base-right"></i>

        <i class="motor-main-housing"></i>
        <i class="motor-horizontal-fins"></i>
        <i class="motor-rear-band"></i>
      </span>
    `,

    current: `
      <i class="bolt"></i>
      <i class="wire"></i>
      <i class="terminal terminal-left"></i>
      <i class="terminal terminal-right"></i>
    `
  };

  let container = null;
  let title = null;
  let subtitle = null;
  let stage = null;
  let grid = null;
  let cards = [];

  let latestWidget = null;
  let pendingFrame = null;
  let resizeObserver = null;

  function createCards() {
    grid.replaceChildren();

    ITEMS.forEach(function (item) {
      const card = document.createElement("div");
      card.className = "tendencia-card";
      card.setAttribute("role", "listitem");

      const icon = document.createElement("span");
      icon.className =
        "tendencia-icon icon-" + item.icon;

      icon.setAttribute("aria-hidden", "true");
      icon.innerHTML = ICONS[item.icon];

      const label = document.createElement("div");
      label.className = "tendencia-label";

      item.lines.forEach(function (text) {
        const line = document.createElement("span");
        line.textContent = text;
        label.appendChild(line);
      });

      card.appendChild(icon);
      card.appendChild(label);
      grid.appendChild(card);
    });

    cards = Array.from(grid.children);
  }

  function updateHeader(widget) {
    if (!title || !subtitle || !grid) return;

    const name =
      widget && typeof widget.name === "string"
        ? widget.name.trim()
        : "";

    /*
     * NOMBRE:
     *
     * LÍNEA 3 / TENDENCIAS
     *
     * Para personalizar también el subtítulo:
     *
     * LÍNEA 3 / TENDENCIAS//Variables del proceso de acabado
     */
    const parts = name.split("//");

    const titleText =
      parts[0].trim() || DEFAULT_TITLE;

    const subtitleText = parts.length > 1
      ? parts.slice(1).join("//").trim()
      : DEFAULT_SUBTITLE;

    title.textContent = titleText;
    subtitle.textContent = subtitleText;
    subtitle.hidden = subtitleText === "";

    grid.setAttribute("aria-label", titleText);

    scheduleLayout();
  }

  function fitHeaderText(element, initialSize) {
    if (!element || element.clientWidth <= 0) return;

    let size = initialSize;
    element.style.fontSize = size + "px";

    while (
      element.scrollWidth > element.clientWidth + 1 &&
      size > 8
    ) {
      size -= 0.5;
      element.style.fontSize = size + "px";
    }
  }

  function chooseLayout(width, height, gap) {
    let best = null;

    for (
      let columns = 1;
      columns <= Math.min(7, cards.length);
      columns++
    ) {
      const rows = Math.ceil(cards.length / columns);

      const cardWidth =
        (width - gap * (columns - 1)) / columns;

      const cardHeight =
        (height - gap * (rows - 1)) / rows;

      if (cardWidth <= 0 || cardHeight <= 0) {
        continue;
      }

      const ratio = cardWidth / cardHeight;

      const emptyCells =
        columns * rows - cards.length;

      const score =
        Math.abs(Math.log(ratio / 2.25)) +
        (emptyCells / cards.length) * 0.2;

      if (!best || score < best.score) {
        best = {
          columns,
          rows,
          cardWidth,
          cardHeight,
          score
        };
      }
    }

    return best;
  }

  function positionCards(columns, rows) {
    cards.forEach(function (card, index) {
      const row = Math.floor(index / columns);
      const column = index % columns;

      const itemsInRow = row === rows - 1
        ? cards.length - row * columns
        : columns;

      /*
       * Centra la última fila.
       * Cada tarjeta ocupa dos columnas pequeñas.
       */
      const offset = columns - itemsInRow;
      const startColumn =
        offset + column * 2 + 1;

      card.style.gridColumn =
        startColumn + " / span 2";

      card.style.gridRow = String(row + 1);
    });
  }

  function resizeLayout() {
    if (
      !container ||
      !title ||
      !subtitle ||
      !grid ||
      !cards.length
    ) {
      return;
    }

    const panelWidth = container.clientWidth;
    const panelHeight = container.clientHeight;

    if (panelWidth <= 0 || panelHeight <= 0) {
      return;
    }

    const padding = Math.min(
      24,
      panelWidth * 0.02,
      panelHeight * 0.035
    );

    container.style.setProperty(
      "--panel-padding",
      padding + "px"
    );

    fitHeaderText(
      title,
      28
    );

    fitHeaderText(
      subtitle,
      14
    );

    const width = grid.clientWidth;
    const height = grid.clientHeight;

    if (width <= 0 || height <= 0) return;

    const gap = Math.min(
      16,
      Math.max(2, Math.min(width, height) * 0.028)
    );

    const layout = chooseLayout(width, height, gap);

    if (!layout) return;

    container.style.setProperty(
      "--tend-tracks",
      String(layout.columns * 2)
    );

    container.style.setProperty(
      "--tend-rows",
      String(layout.rows)
    );

    container.style.setProperty(
      "--tend-gap",
      gap + "px"
    );

    positionCards(layout.columns, layout.rows);

    /*
     * Tamaños moderados para el panel de 1460 × 740.
     * El contenido reduce su tamaño si el panel es menor.
     */
    const scale = Math.min(
      1,
      layout.cardWidth / 260,
      layout.cardHeight / 120
    );

    container.style.setProperty(
      "--card-padding",
      (12 * scale) + "px"
    );

    container.style.setProperty(
      "--card-radius",
      (5 * scale) + "px"
    );

    container.style.setProperty(
      "--card-icon",
      (40 * scale) + "px"
    );

    container.style.setProperty(
      "--card-content-gap",
      (8 * scale) + "px"
    );

    const initialFontSize = 15.5 * scale;

    container.style.setProperty(
      "--card-font",
      initialFontSize + "px"
    );

    /*
     * Ajuste uniforme de las etiquetas según
     * la línea que necesite más espacio.
     */
    let widthFactor = 1;

    const lines = grid.querySelectorAll(
      ".tendencia-label > span"
    );

    lines.forEach(function (line) {
      const available =
        line.parentElement.clientWidth;

      const required = line.scrollWidth;

      if (available > 0 && required > available) {
        widthFactor = Math.min(
          widthFactor,
          available / required
        );
      }
    });

    if (widthFactor < 1) {
      container.style.setProperty(
        "--card-font",
        (initialFontSize * widthFactor * 0.98) + "px"
      );
    }
  }

  function scheduleLayout() {
    if (pendingFrame !== null) return;

    pendingFrame = requestAnimationFrame(function () {
      pendingFrame = null;
      resizeLayout();
    });
  }

  window.onWidgetUpdate = function (widget) {
    latestWidget = widget;
    updateHeader(widget);
  };

  function initialize() {
    container = document.querySelector(
      ".tendencias-widget"
    );

    title = document.querySelector(
      ".tendencias-title"
    );

    subtitle = document.querySelector(
      ".tendencias-subtitle"
    );

    stage = document.querySelector(
      ".tendencias-stage"
    );

    grid = document.querySelector(
      ".tendencias-grid"
    );

    if (
      !container ||
      !title ||
      !subtitle ||
      !stage ||
      !grid
    ) {
      return;
    }

    createCards();

    updateHeader(
      latestWidget || window.WIDGET || null
    );

    resizeLayout();

    if (typeof ResizeObserver !== "undefined") {
      resizeObserver =
        new ResizeObserver(scheduleLayout);

      resizeObserver.observe(container);
      resizeObserver.observe(stage);
    } else {
      window.addEventListener(
        "resize",
        scheduleLayout
      );
    }

    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(scheduleLayout);
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
